--Open an FSDB with Verdi. If --fsdb is not provided, the task picks the
--lexicographically last *.fsdb under build/vcs/sim. If your filenames do not
--sort by testcase/time, pass -f explicitly.
task("verdi", function()
    set_menu {
        usage = "xmake verdi [options]",
        description = "Open FSDB waveform with Verdi",
        options = {
            {"f", "fsdb", "kv", nil, "fsdb file path"}
        }
    }
    on_run(function()
        import("core.base.option")
        local fsdb = option.get("fsdb")
        if not fsdb then
            local fsdbs = os.files(path.join(build_dir, "vcs", "sim", "*.fsdb"))
            table.sort(fsdbs)
            assert(#fsdbs > 0, "no fsdb found in " .. path.join(build_dir, "vcs", "sim"))
            fsdb = fsdbs[#fsdbs]
        end
        os.execv("verdi", {"-ssf", fsdb})
    end)
end)

    -- 打开 VCS 代码覆盖率。此 task 与 `xmake verdi` 分工不同：后者查看
    -- FSDB 时序波形；本 task 以 `-cov` 直接打开包含 RTL shape 与 testcase
    -- 命中数据的 coverage.vdb，显示 RTL 行、条件、分支等覆盖率。
task("verdi_cov", function()
    set_menu {
        usage = "xmake verdi_cov",
        description = "Open cumulative VCS coverage for all recorded testcases"
    }
    on_run(function()
        local cm_root = path.join(build_dir, "vcs", "sim", "cov")
        local vdb = path.join(cm_root, "coverage.vdb")

        -- 所有 testcase 的命中数据都保存在同一个完整 VDB 中。本 task 不
        -- 传 Verdi 的 -tests 筛选参数，因此始终显示所有已运行 testcase
        -- 的累计覆盖率；不需要也不接受 -t 选项。
        -- 缺失 VDB 通常说明尚未执行带覆盖率的 VCS 编译和仿真。
        assert(os.isdir(vdb), "no coverage VDB found: " .. vdb .. "; run xmake vcsall -t <tc> first")
        os.execv("verdi", {"-cov", "-covdir", vdb})
    end)
end)
