-- Keep compatibility with both the supplied template (`sim`) and Verilua's
-- conventional environment variable (`SIM`).
local sim = os.getenv("sim") or "vcs"

local all_testcases = {
    "000",
    "001",
    "002",
    "003",
    "004",
    "005",
    "006",
    "007",
    "008",
